  'ngsl-2358': { example: 'You can adjust the height of the chair.', exampleCs: 'Výšku židle si můžeš upravit.' },
  'ngsl-2359': { example: 'Our art teacher is very creative and full of ideas.', exampleCs: 'Naše učitelka výtvarky je velmi kreativní a plná nápadů.' },
  'ngsl-2360': { example: 'Nowadays, most teenagers have their own phone.', exampleCs: 'V dnešní době má většina teenagerů vlastní telefon.' },
  'ngsl-2362': { example: 'This region is famous for its agricultural products.', exampleCs: 'Tento region je známý svými zemědělskými produkty.' },
  'ngsl-2363': { example: 'The shop lowered its prices to beat its competitors.', exampleCs: 'Obchod snížil ceny, aby porazil své konkurenty.' },
  'ngsl-2364': { example: 'In the Czech Republic, you can\'t buy alcohol until you\'re eighteen.', exampleCs: 'V Česku si alkohol nemůžeš koupit, dokud ti není osmnáct.' },
  'ngsl-2365': { example: 'We are going to a music festival in July.', exampleCs: 'V červenci jedeme na hudební festival.' },
  'ngsl-2366': { example: 'Carrots are my favourite vegetable, especially in soup.', exampleCs: 'Mrkev je moje oblíbená zelenina, hlavně v polévce.' },
  'ngsl-2367': { example: 'The delivery van brought our new sofa this morning.', exampleCs: 'Dodávka nám dnes ráno přivezla nový gauč.' },
  'ngsl-2369': { example: 'Mars is often called the red planet.', exampleCs: 'Marsu se často říká rudá planeta.' },
  'ngsl-2370': { example: 'The graph in our maths book shows a rising curve.', exampleCs: 'Graf v naší učebnici matematiky ukazuje stoupající křivku.' },
  'ngsl-2372': { example: 'It took her years to overcome her fear of flying.', exampleCs: 'Trvalo jí roky, než překonala strach z létání.' },
