  'ngsl-2374': { example: 'The depth of the pool is two metres.', exampleCs: 'Hloubka bazénu je dva metry.' },
  'ngsl-2375': { example: 'Let\'s meet at the main entrance of the cinema.', exampleCs: 'Sejdeme se u hlavního vchodu do kina.' },
  'ngsl-2376': { example: 'Grandpa put another log on the fire.', exampleCs: 'Děda přiložil do ohně další poleno.' },
  'ngsl-2377': { example: 'The story is about a friendly giant who lives in the mountains.', exampleCs: 'Příběh je o přátelském obrovi, který žije v horách.' },
  'ngsl-2379': { example: 'The portions in this restaurant are huge.', exampleCs: 'Porce v téhle restauraci jsou obrovské.' },
  'ngsl-2380': { example: 'Some cleaning products contain dangerous substances.', exampleCs: 'Některé čisticí prostředky obsahují nebezpečné látky.' },
  'ngsl-2381': { example: 'The school library has an extensive collection of English books.', exampleCs: 'Školní knihovna má rozsáhlou sbírku anglických knih.' },
  'ngsl-2382': { example: 'How do you interpret the ending of the film?', exampleCs: 'Jak vykládáš konec toho filmu?' },
  'ngsl-2383': { example: 'Having a part-time job gives me more independence.', exampleCs: 'Brigáda mi dává větší nezávislost.' },
  'ngsl-2385': { example: 'The inner pocket of my jacket is perfect for my phone.', exampleCs: 'Vnitřní kapsa mé bundy je ideální na telefon.' },
  'ngsl-2386': { example: 'Chemicals from factories can do serious harm to rivers.', exampleCs: 'Chemikálie z továren mohou řekám způsobit vážnou škodu.' },
  'ngsl-2387': { example: 'You should consult a doctor if the pain doesn\'t stop.', exampleCs: 'Pokud bolest nepřestane, měl by ses poradit s lékařem.' },
  'ngsl-2388': { example: 'She bought a pink backpack for school.', exampleCs: 'Koupila si do školy růžový batoh.' },
  'ngsl-2390': { example: 'Cut the paper into long, thin strips for the project.', exampleCs: 'Na projekt nastříhej papír na dlouhé úzké pruhy.' },
  'ngsl-2391': { example: 'The baby\'s skin is soft and smooth.', exampleCs: 'Pokožka miminka je jemná a hladká.' },
