  'ngsl-2397': { example: 'The twins dress similarly, so it\'s hard to tell them apart.', exampleCs: 'Dvojčata se oblékají podobně, takže je těžké je rozeznat.' },
  'ngsl-2398': { example: 'The children behaved very well during the trip.', exampleCs: 'Děti se během výletu chovaly velmi dobře.' },
  'ngsl-2399': { example: 'The music at the party was too loud.', exampleCs: 'Hudba na večírku byla příliš hlasitá.' },
  'ngsl-2400': { example: 'What are the dimensions of your bedroom?', exampleCs: 'Jaké rozměry má tvůj pokoj?' },
  'ngsl-2401': { example: 'The first lesson was easy, but subsequent lessons were harder.', exampleCs: 'První hodina byla snadná, ale následné hodiny byly těžší.' },
  'ngsl-2402': { example: 'Wash your hands often to prevent infection.', exampleCs: 'Myj si často ruce, abys předešel infekci.' },
  'ngsl-2403': { example: 'Take a jacket, it might get cold in the evening.', exampleCs: 'Vezmi si bundu, večer může být zima.' },
  'ngsl-2404': { example: 'The new heating system improved the energy efficiency of our house.', exampleCs: 'Nový systém vytápění zlepšil energetickou účinnost našeho domu.' },
  'ngsl-2406': { example: 'One interesting statistic shows that teenagers sleep less than before.', exampleCs: 'Jeden zajímavý statistický údaj ukazuje, že teenageři spí méně než dřív.' },
  'ngsl-2407': { example: 'I go swimming regularly to stay fit.', exampleCs: 'Pravidelně chodím plavat, abych se udržel v kondici.' },
  'ngsl-2408': { example: 'We spent a week in a seaside resort in Croatia.', exampleCs: 'Strávili jsme týden v přímořském letovisku v Chorvatsku.' },
  'ngsl-2409': { example: 'Spinach and red meat contain a lot of iron.', exampleCs: 'Špenát a červené maso obsahují hodně železa.' },
  'ngsl-2410': { example: 'The match will be broadcast live on TV tonight.', exampleCs: 'Zápas bude dnes večer vysílán živě v televizi.' },
  'ngsl-2411': { example: 'Membership of the gym costs 500 crowns a month.', exampleCs: 'Členství v posilovně stojí 500 korun měsíčně.' },
  'ngsl-2412': { example: 'Could you buy some fresh bread on your way home?', exampleCs: 'Mohl bys cestou domů koupit čerstvý chleba?' },
  'ngsl-2414': { example: 'The air in the mountains is pure and fresh.', exampleCs: 'Vzduch na horách je čistý a svěží.' },
  'ngsl-2415': { example: 'I fell off my bike and got a bloody knee.', exampleCs: 'Spadl jsem z kola a měl jsem celé krvavé koleno.' },
  'ngsl-2416': { example: 'In this game, you can choose an ally to help you.', exampleCs: 'V této hře si můžeš vybrat spojence, který ti pomůže.' },
  'ngsl-2417': { example: 'We bought a large quantity of food for the party.', exampleCs: 'Na večírek jsme koupili velké množství jídla.' },
  'ngsl-2418': { example: 'Bend your knees when you lift something heavy.', exampleCs: 'Když zvedáš něco těžkého, ohni kolena.' },
