  'ngsl-2420': { example: 'Can you briefly explain the rules of the game?', exampleCs: 'Můžeš stručně vysvětlit pravidla hry?' },
  'ngsl-2421': { example: 'The fire alarm went off during our maths lesson.', exampleCs: 'Během hodiny matematiky se spustil požární poplach.' },
  'ngsl-2422': { example: 'Please don\'t disturb me, I\'m studying for a test.', exampleCs: 'Prosím, neruš mě, učím se na test.' },
  'ngsl-2423': { example: 'It\'s hard to sustain your motivation during a long school year.', exampleCs: 'Během dlouhého školního roku je těžké udržet si motivaci.' },
  'ngsl-2424': { example: 'The new wall protects the town from floods.', exampleCs: 'Nová zeď chrání město před povodněmi.' },
