  'ngsl-2426': { example: 'My friends think I\'m crazy for swimming in cold water.', exampleCs: 'Kamarádi si myslí, že jsem šílený, když plavu ve studené vodě.' },
  'ngsl-2427': { example: 'Always cite your sources when you write an essay.', exampleCs: 'Když píšeš esej, vždycky cituj své zdroje.' },
  'ngsl-2428': { example: 'We visited the newly opened science museum.', exampleCs: 'Navštívili jsme nově otevřené muzeum vědy.' },
  'ngsl-2429': { example: 'Draw two parallel lines on your paper.', exampleCs: 'Nakresli na papír dvě rovnoběžné čáry.' },
  'ngsl-2430': { example: 'The form asks for your name, age and gender.', exampleCs: 'Ve formuláři se vyplňuje jméno, věk a pohlaví.' },
  'ngsl-2431': { example: 'A local bakery is the main sponsor of our football team.', exampleCs: 'Hlavním sponzorem našeho fotbalového týmu je místní pekárna.' },
