  'ngsl-2435': { example: 'Press the red button to start the machine.', exampleCs: 'Stiskni červené tlačítko a spusť stroj.' },
  'ngsl-2436': { example: 'Heavy school bags are a real burden for young children.', exampleCs: 'Těžké školní tašky jsou pro malé děti opravdové břemeno.' },
  'ngsl-2437': { example: 'We rode camels in the desert in Morocco.', exampleCs: 'V Maroku jsme jezdili na velbloudech po poušti.' },
  'ngsl-2438': { example: 'I\'m going to the cinema with my mates tonight.', exampleCs: 'Dnes večer jdu s kamarády do kina.' },
  'ngsl-2440': { example: 'The company\'s shareholders met to discuss the new plan.', exampleCs: 'Akcionáři společnosti se sešli, aby probrali nový plán.' },
  'ngsl-2441': { example: 'I have a bowl of cereal for breakfast every morning.', exampleCs: 'Každé ráno si dám k snídani misku cereálií.' },
  'ngsl-2442': { example: 'The discovery of penicillin changed medicine forever.', exampleCs: 'Objev penicilinu navždy změnil medicínu.' },
  'ngsl-2443': { example: 'There was some resistance to the new school rules.', exampleCs: 'Proti novým školním pravidlům byl určitý odpor.' },
  'ngsl-2444': { example: 'I like to have a hot bath after skiing.', exampleCs: 'Po lyžování si rád dám horkou koupel.' },
