  'ngsl-2446': { example: 'Don\'t criticize others if you can\'t do it better.', exampleCs: 'Nekritizuj ostatní, když to sám neumíš líp.' },
  'ngsl-2447': { example: 'Turn off the tap while you brush your teeth.', exampleCs: 'Při čištění zubů zavři kohoutek.' },
  'ngsl-2448': { example: 'My sister is studying philosophy at university.', exampleCs: 'Moje sestra studuje na univerzitě filozofii.' },
  'ngsl-2449': { example: 'My lips get dry in winter, so I use lip balm.', exampleCs: 'V zimě mám suché rty, a proto používám balzám na rty.' },
